 // Now demonstrate TryGetTypeInfo returning false.
 // A resolver that only resolves Person (returns null for everything else).
 var limited = new JsonSerializerOptions
 {
     TypeInfoResolver = new PersonOnlyResolver()
 };

 if (limited.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo))
 {
     Console.WriteLine($"Unexpected: got info for int");
 }
 else
 {
     Console.WriteLine("TryGetTypeInfo<int> returned false — no exception thrown");
 }

 public record Person(string Name, int Age);

 /// A resolver that only knows how to produce metadata for Person.
 sealed class PersonOnlyResolver : IJsonTypeInfoResolver
 {
     private readonly DefaultJsonTypeInfoResolver _inner = new();

     public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
     {
         if (type == typeof(Person))
             return _inner.GetTypeInfo(type, options);

         return null; // signals "not available"
     }
 }
